// Animation loop
function animate() {
    // Clear canvas with sky
    ctx.fillStyle = '#87CEEB';
    ctx.fillRect(0, 0, W, H);

    // Draw ground
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(0, 300, W, 100);

    // Draw wind lines
    ctx.strokeStyle = '#FFFFFF';
    ctx.lineWidth = 1;
    for (let i = 0; i < 15; i++) {
        const x = (i * 50 + Date.now() * 0.01) % (W + 100) - 50;
        const y = Math.random() * 300;
        const len = 15 + Math.sin(Date.now() * 0.001 + i) * 10;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + len, y + Math.sin(i) * 5);
        ctx.stroke();
    }

    // Draw and update leaves
    leaves.forEach(leaf => {
        leaf.y += leaf.speed;
        leaf.x += leaf.wind + Math.sin(leaf.angle) * 0.5;
        leaf.angle += leaf.spin;

        // Reset leaf if it goes off screen
        if (leaf.y > H || leaf.x < -10 || leaf.x > W + 10) {
            leaf.x = Math.random() * W;
            leaf.y = -10;
            leaf.wind = (Math.random() - 0.5) * 0.5;
            leaf.angle = Math.random() * Math.PI * 2;
        }

        // Draw leaf
        ctx.save();
        ctx.translate(leaf.x, leaf.y);
        ctx.rotate(leaf.angle);
        ctx.fillStyle = `rgb(${180 + Math.random() * 50}, ${60 + Math.random() * 40}, 0)`;
        ctx.fillRect(-leaf.size/2, -leaf.size/2, leaf.size, leaf.size);
        ctx.restore();
    });

    requestAnimationFrame(animate);
}

