// Firework particles
function drawFirework(x, y, color) {
    const particles = [];
    const particleCount = 100;

    for (let i = 0; i < particleCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 3 + 1;
        const vx = Math.cos(angle) * speed;
        const vy = Math.sin(angle) * speed;
        const size = Math.random() * 2 + 1;

        particles.push({
            x: x,
            y: y,
            vx: vx,
            vy: vy,
            size: size,
            color: color,
            life: 1
        });
    }

    return particles;
}

// Draw fireworks
const fireworks = [];
fireworks.push(...drawFirework(100, 300, '#ff0'));
fireworks.push(...drawFirework(300, 250, '#f0f'));
fireworks.push(...drawFirework(200, 200, '#0ff'));
fireworks.push(...drawFirework(150, 150, '#ff0'));
fireworks.push(...drawFirework(250, 100, '#f0f'));

// Animation loop
let frame = 0;
function animate() {
    frame++;

    // Clear with semi-transparent black for trail effect
    ctx.fillStyle = 'rgba(0, 0, 0, 0.1)';
    ctx.fillRect(0, 0, W, H);

    // Redraw stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 100; i++) {
        const x = Math.random() * W;
        const y = Math.random() * H;
        const size = Math.random() * 1.5;
        ctx.fillRect(x, y, size, size);
    }

    // Update and draw particles
    for (let i = fireworks.length - 1; i >= 0; i--) {
        const p = fireworks[i];

        p.x += p.vx;
        p.y += p.vy;
        p.vy += 0.05; // gravity
        p.life -= 0.01;

        if (p.life <= 0) {
            fireworks.splice(i, 1);
            continue;
        }

        ctx.fillStyle = p.color;
        ctx.globalAlpha = p.life;
        ctx.fillRect(p.x, p.y, p.size, p.size);
    }

    ctx.globalAlpha = 1;

    // Random new fireworks
    if (frame % 100 === 0) {
        const x = Math.random() * W;
        const y = Math.random() * (H/2) + H/2;
        const colors = ['#ff0', '#f0f', '#0ff', '#f00', '#0f0'];
        fireworks.push(...drawFirework(x, y, colors[Math.floor(Math.random() * colors.length)]));
    }

    if (frame < 500) {
        requestAnimationFrame(animate);
    }
}

