// Draw flowers
function drawFlower(x, y, color) {
    // Stem
    ctx.fillStyle = '#228B22';
    ctx.fillRect(x, y, 4, 40);

    // Flower center
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.arc(x + 2, y, 8, 0, Math.PI * 2);
    ctx.fill();

    // Petals
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x + 2, y - 5, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(x + 2, y + 45, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(x - 5, y + 20, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(x + 9, y + 20, 6, 0, Math.PI * 2);
    ctx.fill();
}

