    // Wings
    ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
    ctx.beginPath();
    ctx.arc(x + 4, y - 2, 6, 0, Math.PI * 2);
    ctx.fill();

    // Legs
    ctx.fillStyle = '#000';
    ctx.fillRect(x, y + 2, 2, 2);
    ctx.fillRect(x + 4, y + 2, 2, 2);
    ctx.fillRect(x + 8, y + 2, 2, 2);
}

