// Draw bees
function drawBee(x, y) {
    // Body
    ctx.fillStyle = '#FFD700';
    ctx.fillRect(x, y, 12, 6);

    // Head
    ctx.fillStyle = '#FFD700';
    ctx.fillRect(x-4, y-2, 6, 6);

    // Wings
    ctx.fillStyle = '#E0FFFF';
    ctx.fillRect(x+2, y-3, 8, 4);
    ctx.fillRect(x+2, y+6, 8, 4);

    // Antennae
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x-2, y);
    ctx.lineTo(x-4, y-2);
    ctx.moveTo(x-2, y);
    ctx.lineTo(x-4, y+2);
    ctx.stroke();
}

