// Draw stack of vinyl records
const recordCount = 5;
const centerX = W / 2;
const baseY = H - 50;
const recordRadius = 100;
const stackOffset = 15;

for (let i = 0; i < recordCount; i++) {
  const y = baseY - i * stackOffset;

  // Outer circle (vinyl)
  ctx.beginPath();
  ctx.arc(centerX, y, recordRadius, 0, Math.PI * 2);
  ctx.fillStyle = '#111';
  ctx.fill();

  // Inner circle (label)
  ctx.beginPath();
  ctx.arc(centerX, y, recordRadius * 0.2, 0, Math.PI * 2);
  ctx.fillStyle = '#fff';
  ctx.fill();

  // Center label
  ctx.beginPath();
  ctx.arc(centerX, y, recordRadius * 0.05, 0, Math.PI * 2);
  ctx.fillStyle = '#333';
  ctx.fill();

  // Grooves
  ctx.strokeStyle = '#444';
  ctx.lineWidth = 1;
  for (let j = 0; j < 12; j++) {
    const angle = (j / 12) * Math.PI * 2;
    const x1 = centerX + Math.cos(angle) * recordRadius * 0.1;
    const y1 = y + Math.sin(angle) * recordRadius * 0.1;
    const x2 = centerX + Math.cos(angle) * recordRadius * 0.8;
    const y2 = y + Math.sin(angle) * recordRadius * 0.8;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }
}

