    // Create a gradient for each segment
    const gradient = ctx.createLinearGradient(
        cx + Math.cos(angle) * 100,
        cy + Math.sin(angle) * 100,
        cx + Math.cos(angle + Math.PI/3) * 100,
        cy + Math.sin(angle + Math.PI/3) * 100
    );

    gradient.addColorStop(0, `hsl(${i * 60}, 100%, 50%)`);
    gradient.addColorStop(1, `hsl(${(i * 60 + 30) % 360}, 100%, 30%)`);

    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(
        cx + Math.cos(angle) * 200,
        cy + Math.sin(angle) * 200
    );
    ctx.lineTo(
        cx + Math.cos(angle + Math.PI/3) * 200,
        cy + Math.sin(angle + Math.PI/3) * 200
    );
    ctx.closePath();
    ctx.fillStyle = gradient;
    ctx.fill();

    // Add some pattern elements
    ctx.fillStyle = `hsla(${(i * 60 + 180) % 360}, 100%, 70%, 0.7)`;
    for (let j = 0; j < 10; j++) {
        const radius = 20 + j * 15;
        const segmentAngle = angle + Math.PI/6;
        const x = cx + Math.cos(segmentAngle) * radius;
        const y = cy + Math.sin(segmentAngle) * radius;
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, Math.PI * 2);
        ctx.fill();
    }
}

