const cols = Math.ceil(W / triangleSize);

for (let row = 0; row < rows; row++) {
  for (let col = 0; col < cols; col++) {
    const x = col * triangleSize;
    const y = row * triangleSize;

    // Random color
    const colors = ['#ff6b6b', '#4ecdc4', '#45b7d1', '#96ceb4', '#feca57', '#ff9ff3'];
    const color = colors[Math.floor(Math.random() * colors.length)];

    // Random triangle orientation
    const orientation = Math.floor(Math.random() * 4);

    ctx.fillStyle = color;

    switch(orientation) {
      case 0: // Up
        ctx.beginPath();
        ctx.moveTo(x + triangleSize/2, y);
        ctx.lineTo(x, y + triangleSize);
        ctx.lineTo(x + triangleSize, y + triangleSize);
        ctx.closePath();
        ctx.fill();
        break;
      case 1: // Down
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + triangleSize, y);
        ctx.lineTo(x + triangleSize/2, y + triangleSize);
        ctx.closePath();
        ctx.fill();
        break;
      case 2: // Left
        ctx.beginPath();
        ctx.moveTo(x, y + triangleSize/2);
        ctx.lineTo(x + triangleSize, y);
        ctx.lineTo(x + triangleSize, y + triangleSize);
        ctx.closePath();
        ctx.fill();
        break;
      case 3: // Right
        ctx.beginPath();
        ctx.moveTo(x + triangleSize, y + triangleSize/2);
        ctx.lineTo(x, y);
        ctx.lineTo(x, y + triangleSize);
        ctx.closePath();
        ctx.fill();
        break;
    }
  }
}

